import assert from "node:assert/strict";
import test from "node:test";
import { JobQueue } from "../src/queue.mjs";
import { backoffDelay } from "../src/retry.mjs";

test("respects capacity, FIFO ties, and backoff cap", () => {
  const q = new JobQueue(2);
  q.push("a", 1);
  q.push("b", 1);
  assert.throws(() => q.push("c", 1));
  assert.equal(q.pop(), "a");
  assert.equal(backoffDelay(10, 100, 500), 500);
});
